import sys

s = sys.stdin.read().split()[0]
n = len(s)
cnt = 0
for i in range(n):
    for j in range(i + 1, n + 1):
        sub = s[i:j]
        if any(sub.count(c) % 2 == 1 for c in set(sub)):
            cnt += 1
print(cnt)

